def enclosed_cells2(g, bg=9):
    H,W=len(g),len(g[0])
    walls={v for row in g for v in row if v!=bg}
    seen=[[False]*W for _ in range(H)]
    q=deque()
    for r in range(H):
        for c in (0,W-1):
            if g[r][c] not in walls and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if g[r][c] not in walls and not seen[r][c]: seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and g[nr][nc] not in walls:
                seen[nr][nc]=True; q.append((nr,nc))
    return [(r,c) for r in range(H) for c in range(W) if g[r][c]==bg and not seen[r][c]]

